exercises.starter:
def weight_report(weights, max_ratio=20.0):
    n_eff = sum(weights) ** 2 / sum(w * w for w in weights)
    return {"status": "PASS", "n": len(weights), "n_eff": n_eff, "deff": len(weights) / n_eff}
